INSERT INTO `node__body` VALUES ('page',0,1,1,'en',0,'<p>Lorem ipsum.</p>','','basic_html'),('speaker',0,2,2,'en',0,'<p>Jatin Sapru is an Indian sports broadcaster-television host and cricket commentator who works for Star Sports network. He also has a YouTube channel, \'Jatin Sapru\', where he uploads vlogs etc.</p>','','basic_html'),('speaker',0,3,3,'en',0,'<p><em>Simerjeet Singh</em> is a dynamic motivational speaker, leadership coach, and keynote speaker known for his energetic and impactful presentations.</p>','','basic_html'),('speaker',0,4,16,'en',0,'<p>Dries Buytaert is the founder and project lead of Drupal, an open-source content management framework powering millions of websites worldwide. He is also the co-founder and CTO of Acquia, a leading cloud platform for building, delivering, and optimizing digital experiences. Dries has been instrumental in building and guiding the Drupal community for over two decades, inspiring thousands of developers and organizations globally.</p>','','basic_html'),('speaker',0,5,5,'en',0,'<p>Arunima Sinha is an Indian mountaineer and sportswoman. She is India\'s first amputee and world\'s first female amputee to scale Mount Everest, Mount Kilimanjaro, Mount Elbrus, Mount Kosciuszko, Aconcagua, Denali and Vinson Massif. She is also a seven time Indian volleyball player.</p>','','basic_html'),('events',0,6,7,'en',0,'<p>A thrilling inter-college cricket tournament where teams from various universities will compete for the championship trophy. Join us for an exciting day full of boundaries, wickets, and cheers.</p>','','basic_html'),('events',0,7,9,'en',0,'<p>Participate in our annual marathon aimed at spreading awareness about fitness and healthy living. Runners from across the city are welcome.</p>','','basic_html'),('events',0,8,10,'en',0,'<p>An interactive session where industry experts guide students on future career opportunities, AI trends, and skill development.</p>','','basic_html'),('events',0,9,11,'en',0,'<p>A platform for youngsters to discuss innovation, leadership, and global challenges that shape the future.</p>','','basic_html'),('events',0,10,14,'en',0,'<p>A thrilling trekking expedition to promote adventure sports and encourage eco-tourism among youth. Includes basic survival training and group activities.</p>','','basic_html'),('events',0,11,15,'en',0,'<p>A fun-filled adventure weekend with camping, kayaking, and group activities designed to boost teamwork and thrill.</p>','','basic_html'),('events',0,12,17,'en',0,'<p>DrupalCamp Delhi 2025 brings together Drupal enthusiasts, developers, designers, and business leaders for a weekend of knowledge-sharing, networking, and community building. Sessions will cover Drupal 10/11, headless CMS, performance optimization, and community contributions.</p>','','basic_html'),('events',0,13,19,'en',0,'<p>DrupalCon Europe 2025 is the premier event for the global Drupal community. It features keynote sessions from Drupal leaders, contribution sprints, workshops, and networking opportunities with industry experts. Perfect for anyone passionate about open-source and digital innovation.</p>','','basic_html'),('events',0,16,28,'en',0,'<p>Experience the thrill as top football clubs clash in the ultimate showdown of the season. A celebration of skill, teamwork, and passion for the game.</p>','','basic_html'),('events',0,17,31,'en',0,'<p>Young and professional swimmers from across the state participate to showcase speed, endurance, and discipline in water sports.</p>','','basic_html'),('events',0,18,30,'en',0,'<p>An inspiring summit featuring keynote sessions from industry leaders and motivational speakers on success, resilience, and leadership.</p>','','basic_html');
/*!40000 ALTER TABLE `node__body` ENABLE KEYS */;
UNLOCK TABLES;

