LOCK TABLES `search_dataset` WRITE;
/*!40000 ALTER TABLE `search_dataset` DISABLE KEYS */;
INSERT INTO `search_dataset` VALUES (1,'en','help_search',' exporting your complete site configuration goal create and download an archive containing all your site s configuration exported as yaml files see managing and deploying configuration for more information about configuration steps in the manage administrative menu navigate to configuration   development   configuration synchronization   export  click export and save the archive file  ',0),(1,'en','node_search',' home page home page aryan mon 8182025 1110 lorem ipsum  ',0),(2,'en','help_search',' importing your complete site configuration goal import the complete configuration of your site from an archive file such as one that was previously exported see exporting your complete site configuration see managing and deploying configuration for more information about configuration steps in the manage administrative menu navigate to configuration   development   configuration synchronization   import  browse to find the configuration archive that you want to import click upload  your configuration archive will be unpacked and placed in the configuration synchronization directory and you will be redirected to the synchronize page review the differences between your uploaded configuration and the active configuration if any and click import all to import the changes  ',0),(2,'en','node_search',' jatin sapru jatin sapru aryan tue 8192025 536 jatin sapru is an indian sports broadcastertelevision host and cricket commentator who works for star sports network he also has a youtube channel jatin sapru where he uploads vlogs etc  ',0),(3,'en','help_search',' exporting a single configuration item goal export a single configuration item to a file see managing and deploying configuration for more information about configuration steps in the manage administrative menu navigate to configuration   development   configuration synchronization   export   single item  select the configuration type that you want to export and then select the specific configuration name to export use your browser to copy the text in the box marked here is your configuration to the clipboard paste the copied text into a plaintext editor on your computer or other device and save it using the suggested file name below the text box  ',0),(3,'en','node_search',' simerjeet singh simerjeet singh aryan tue 8192025 537 simerjeet singh is a dynamic motivational speaker leadership coach and keynote speaker known for his energetic and impactful presentations  ',0),(4,'en','help_search',' importing a single configuration item goal import a single configuration item in yaml format such as one that was previously exported see exporting a single configuration item see managing and deploying configuration for more information about configuration steps in the manage administrative menu navigate to configuration   development   configuration synchronization   import   single item  select the configuration type that you want to import on your computer or other device copy the yamlformat configuration that you want to import to the clipboard paste the clipboard text into the box labeled paste your configuration here  click import   ',0),(4,'en','node_search',' dries buytaert dries buytaert aryan tue 8192025 539 dries buytaert is the founder and project lead of drupal an opensource content management framework powering millions of websites worldwide he is also the cofounder and cto of acquia a leading cloud platform for building delivering and optimizing digital experiences dries has been instrumental in building and guiding the drupal community for over two decades inspiring thousands of developers and organizations globally  ',0),(5,'en','help_search',' managing contact forms what are contact forms  there are two different types of contact forms provided by the core contact module personal contact forms which allow users to contact other users on the site and sitewide contact forms which allow users to contact site managers or administrators a site can have more than one sitewide contact form each has its own fields to fill out recipients and url you can also change the fields that are shown on personal contact forms using the personal contact form site visitors can email registered users on your site by using the personal contact form without knowing or learning the email address of the recipient when a user with the correct permissions is viewing another user s profile the viewer will see a contact tab or link which leads to the personal contact form if the user whose profile is being viewed has their personal contact form enabled this is a user account setting  contact form management tasks see the related topics below for specific tasks  ',0),(5,'en','node_search',' arunima sinha arunima sinha aryan tue 8192025 541 arunima sinha is an indian mountaineer and sportswoman she is india s first amputee and world s first female amputee to scale mount everest mount kilimanjaro mount elbrus mount kosciuszko aconcagua denali and vinson massif she is also a seven time indian volleyball player  ',0),(6,'en','help_search',' setting a default contact form goal set a sitewide contact form to be the default contact form  the form displayed on the default contact page  for example   contact   steps in the manage administrative menu navigate to structure   contact forms  click edit for the sitewide form you want to be the default check make this the default form and click save   ',0),(6,'en','node_search',' intercollege cricket tournament intercollege cricket tournament aryan tue 8192025 555 a thrilling intercollege cricket tournament where teams from various universities will compete for the championship trophy join us for an exciting day full of boundaries wickets and cheers tue 8192025 1130 fri 8222025 1130 eden gardens kolkata jatin sapru ',0),(7,'en','help_search',' creating a new contact form goal create a new sitewide contact form steps in the manage administrative menu navigate to structure   contact forms  click add contact form  fill in the label  title for the form  recipients  and optionally the other settings click save  you should see your new contact form in the table along with a link to view it the contact form will always have subject and message fields if you want to add more fields follow the steps in managing the fields of contact forms  ',0),(7,'en','node_search',' annual marathon for health annual marathon for health aryan tue 8192025 606 participate in our annual marathon aimed at spreading awareness about fitness and healthy living runners from across the city are welcome thu 8072025 1136 thu 8072025 2336 india gate new delhi arunima sinha ',0),(8,'en','help_search',' configuring personal contact forms goal configure personal contact forms for registered users on the website steps in the manage administrative menu navigate to configuration   people   account settings  in the contact settings section check uncheck the box to enable disable the contact form for new user accounts click save configuration  in the manage administrative menu navigate to people   permissions  verify that permissions are correct for your site s roles including the generic anonymous user and authenticated user  in order to use personal contact forms users need both view user information  in the user section which enables them to view user profiles and use users personal contact forms  in the contact section which enables them to use contact forms if they can view user profiles click save permissions  the contact form will always have subject and message fields if you want to add more fields follow the steps in managing the fields of contact forms  ',0),(8,'en','node_search',' youth dialogue on future careers youth dialogue on future careers aryan tue 8192025 609 an interactive session where industry experts guide students on future career opportunities ai trends and skill development tue 9022025 1140 tue 9022025 245 indian institute of technology iit mumbai simerjeet singh ',0),(9,'en','help_search',' managing the fields of contact forms goal add remove or rearrange the fields on personal and sitewide contact forms what are the fields on contact forms  both personal and sitewide contact forms will always have subject and message fields you can add additional fields for users to fill out if desired note that if you want to display other content on a form page such as text or images you can use a content block steps in the manage administrative menu navigate to structure   contact forms  click manage fields for the form you want to change the fields of and add or remove one or more fields on the form click manage form display to change the order or configuration of the fields on the form  ',0),(9,'en','node_search',' future leaders conclave future leaders conclave aryan tue 8192025 615 a platform for youngsters to discuss innovation leadership and global challenges that shape the future wed 9172025 1200 wed 9172025 1450 hyderabad international convention centre simerjeet singh ',0),(10,'en','help_search',' using the administrative interface what administrative interface components are available  the following administrative interface components are provided by the core software and its modules some contributed modules offer additional functionality accessibility features to enable all users to perform administrative tasks see accessibility of the administrative interface for more information a menu system which you can navigate to find pages for administrative tasks the core toolbar module displays this menu on the top or left side of the page right side in righttoleft languages there are also contributed module replacements for the core toolbar module with additional features such as the admin toolbar module  the core shortcuts module enhances the toolbar with a configurable list of links to commonlyused tasks if you install the core contextual links module nonadministrative pages will contain links leading to related administrative tasks inplace or quick editing inplace editing of configuration is provided by the core settings tray module see using inline quick settings editing for more information the core help module displays help topics and provides a help block that can be placed on administrative pages to provide an overview of their functionality what are the sections of the administrative menu  the administrative menu which you can navigate by visiting  admin on your site or by using an administrative toolbar has the following sections some may not be available depending on which modules are currently installed on your site and your permissions  content  find manage and create new pages manage comments and files structure  place and edit blocks set up content types and fields configure menus administer taxonomy and configure some contributed modules appearance  switch between themes install themes and update existing themes extend  update install and uninstall modules configuration  configure the settings for various site functionality including some contributed modules people  manage user accounts and permissions reports  display information about site security necessary updates and site activity help  get help on using the administrative interface administrative interface overview install the core modules mentioned above to use the corresponding aspect of the administrative interface see the related topics listed below for more details on some aspects of the administrative interface  ',0),(10,'en','node_search',' himalayan trekking challenge himalayan trekking challenge aryan tue 8192025 617 a thrilling trekking expedition to promote adventure sports and encourage ecotourism among youth includes basic survival training and group activities thu 8282025 1100 wed 9032025 1300 manali himachal pradesh arunima sinha ',0),(11,'en','help_search',' configuring help search goal set up your site so that users can search for help steps in the manage administrative menu navigate to extend  verify that the search help and block modules are installed or install them if they are not already installed in the manage administrative menu navigate to configuration   search and metadata   search pages  verify that a help search page is listed in the search pages section if not add a new page of type help  check the indexing status of the help search page if it is not fully indexed see running and configuring cron about how to run cron until indexing is complete in the future you can click rebuild search index on this page or clearing the site cache in order to force help topic text to be reindexed for searching this should be done whenever a module theme language or string translation is updated in the manage administrative menu navigate to structure   block layout  click the link for your administrative theme such as the core claro theme near the top of the page and verify that there is already a search block for help located in the help region if not follow the steps in the related topic to place the search form block in the help region when configuring the block choose help as the search page and in the pages tab under visibility  enter  admin help to make the search form only visible on the main help page in the manage administrative menu navigate to help  verify that the search block is visible and try a search  ',0),(11,'en','node_search',' riverside camping adventure games riverside camping adventure games aryan tue 8192025 624 a funfilled adventure weekend with camping kayaking and group activities designed to boost teamwork and thrill thu 8072025 1154 sat 8092025 1154 rishikesh uttarakhand arunima sinha ',0),(12,'en','help_search',' extending and modifying your site functionality what is a module  a module is a set of php javascript and or css files that extends site features and adds functionality a set of core modules is distributed as part of the core software download additional contributed modules can be downloaded separately from the download extend page on drupalorg  what is an experimental module  an experimental module is a module that is still in development and is not yet stable using experimental modules on production sites is not recommended what are installing and uninstalling  installing a core or downloaded contributed module means turning it on so that you can use its features and functionality uninstalling means turning it off and removing all of its configuration a module cannot be uninstalled if another installed module depends on it or if you have created content on your site using the module you would need to delete the content and uninstall dependent modules first extending overview see the related topics listed below for help performing tasks related to extending the functionality of your site additional resources concept modules drupal user guide  extending and customizing your site drupal user guide  ',0),(12,'en','node_search',' drupalcamp delhi 2025 drupalcamp delhi 2025 aryan tue 8192025 631 drupalcamp delhi 2025 brings together drupal enthusiasts developers designers and business leaders for a weekend of knowledgesharing networking and community building sessions will cover drupal 1011 headless cms performance optimization and community contributions sat 9062025 2 sun 9072025 2 pragati maidan new delhi dries buytaert ',0),(13,'en','help_search',' maintaining and troubleshooting your site maintaining and troubleshooting overview here are some tasks and hints related to maintaining your site and troubleshooting problems that may come up on your site see the related topics below for more information when performing maintenance such as installing uninstalling or updating a module put your site in maintenance mode configure your site so that cron runs periodically if your site is not behaving as expected clear the cache before trying to diagnose the problem there are several site reports that can help you diagnose problems with your site there are also two core modules that can be used for error logging database logging and syslog additional resources preventing and fixing problems drupal user guide  security and maintenance drupal user guide  ',0),(13,'en','node_search',' drupalcon europe 2025 drupalcon europe 2025 aryan tue 8192025 634 drupalcon europe 2025 is the premier event for the global drupal community it features keynote sessions from drupal leaders contribution sprints workshops and networking opportunities with industry experts perfect for anyone passionate about opensource and digital innovation wed 8202025 1205 sat 8232025 1205 barcelona spain dries buytaert ',0),(14,'en','help_search',' working with help topics what is a help topic  a help topic describes a concept or steps to accomplish a task related to a feature provided by one or more modules or themes if the core search module is enabled these topics are also searchable where are help topics listed  the toplevel help topics are listed at help links to other topics including nontoplevel help topics can be found under the related heading when viewing a topic page how are help topics provided  modules and themes can provide help topics as twigfilebased plugins in a project subdirectory called helptopics  plugin metadata is provided in yaml front matter within each twig file pluginbased help topics provided by modules and themes will automatically be updated when a module or theme is updated use the plugins in core modules help helptopics as a guide when writing and formatting a help topic plugin for your theme or module how are help topics translated  the title and body text of help topics provided by contributed modules and themes are translatable using user interface translation provided by interface translation module topics provided by custom modules and themes are also translatable if they have been viewed at least once in a nonenglish language which triggers putting their translatable text into the translation database how can users search for help topics  to enable users to search help including help topics you will need to install the core search module configure a search page and add a search block to the help page or another administrative page a search page is provided automatically and if you use the core claro administrative theme a help search block is shown on the main help page then users with search permissions and permission to view help will be able to search help see the related topic configuring help search for stepbystep instructions additional resources help topics standards ',0),(14,'en','node_search',' drupalcon drupalcon aryan wed 8202025 559 tue 8192025 1129 thu 8212025 1429 eden gardens kolkata arunima sinha ',0),(15,'en','help_search',' managing and deploying configuration what is the configuration system  the configuration system provides the ability for administrators to customize the site and to move and synchronize configuration changes between development sites and the live site it does this in 2 ways providing storage for configuration providing a process in which configuration changes can be imported and exported between instances of the same site for example from dev to staging to live  what is configuration data  configuration data describes settings that define how your site behaves or is displayed for example when a site administrator updates settings using an administrative form these settings are stored as configuration data configuration data describes settings as simple as a site name and as complex as a view or image style what kinds of configuration are there  active configuration active configuration is the current working configuration of a site storage of active configuration is defined by the site and resides in the database by default simple configuration a simple configuration item is a group of settings such as the settings for a module or theme each simple configuration item has its own unique structure configuration entities configuration entities are userdefined configuration items grouped by type such as views image styles and content types each configuration entity within a type has a similar structure default configuration default configuration can be defined by a module theme or installation profile in its config install or config optional directories configuration is provided in yaml files file extension yml yaml is a humanreadable data serialization standard that is used by the core software for several purposes once the default configuration has been imported into the site s active configuration through installing the extension that configuration is owned by the site not the extension this means that future updates of the extension will not override the site s active configuration for that extension what is configuration synchronization  configuration synchronization is the process of exporting and importing configuration to keep configuration synchronized between different versions of a site for example between a development site and the live site each site has unique identifier also called a uuid  which identifies the site to the system in any instance of the site as long as the site instances have been reproduced as clones cloning is when the codebase and database are copied to create a new site instance when site instances are cloned a dev instance of the site has the same uuid as the live instance when site instances share the same uuid configuration can be exported from one instance to another the following list contains terms and concepts related to configuration synchronization exported configuration when configuration is exported the active configuration is exported as a set of files in yaml format when using the configuration synchronization administrative ui configuration can be exported as a fullexport or singleitem archive this archive can then be imported into the destination site instance imported configuration imported configuration is configuration that has been exported from another instance of the site the source and is now being imported into another site instance the destination thereby updating its active configuration to match the imported configuration data set configuration sync directory the configuration sync directory location is set in the site s settingsphp file when configuration is exported the active configuration is exported and described in yaml files which are stored in the configuration sync directory after the first export the system compares the site s active configuration with the configuration data in the sync directory and will only export active configuration items that are different than their counterparts in the sync directory managing configuration overview configuration management tasks such as exporting or importing configuration and synchronizing configuration can be done either through the administrative ui provided by the core configuration manager module or a commandline interface cli tool defining a configuration sync directory path other than the default value requires read write access to the site s settingsphp file most modules and themes also provide settings forms for updating the configuration they provide see the related topics listed below for specific tasks additional resources configuration management workflow using drush concept types of data drupal user guide  concept development sites drupal user guide  making a development site drupal user guide  ',0),(15,'en','node_search',' listing page listing page aryan wed 8202025 623  ',0),(16,'en','help_search',' using inline quick settings editing goal edit settings in place what is quick editing  the core settings tray module provides the ability to quickly edit settings inline it requires the core contextual links module in order to expose the links that let you edit in place who can edit settings in place  in order to follow these steps to edit settings in place the core settings tray module must be installed also either the core toolbar module or a contributed replacement must be installed you will need to have use contextual links permission as well as permission to edit the particular content or settings steps find and visit a page on your site that has the settings that you would like to edit click the contextual links edit button on the toolbar in most themes it looks like a pencil contextual edit links with the same icon will appear all over your page find the contextual link for the part of the page you want to edit for example if you want to edit the settings for a block the link should be in the topright corner of the block or topleft for righttoleft languages click the link to open the contextual links menu and click quick edit  an editing form for the settings should appear on the page make your edits and submit the form  ',0),(16,'en','node_search',' national football league finals national football league finals aryan wed 8202025 630 experience the thrill as top football clubs clash in the ultimate showdown of the season a celebration of skill teamwork and passion for the game sat 8302025 1204 sat 9062025 1204 salt lake stadium kolkata jatin sapru ',0),(17,'en','help_search',' managing content structure what types of data does a site have  there are four main types of data content is the information text images etc meant to be displayed to website visitors configuration is data that defines how the content is displayed some configuration such as field labels may also be visible to site visitors state is temporary data about the state of your site such as the last time the system cron jobs ran session is a subset of state information related to users interactions with the site such as site cookies and whether or not they are logged in what is a content entity  a content entity  or more commonly  entity  is an item of content data which can consist of text html markup images attached files and other data content entities are grouped into entity types  which have different purposes and are displayed in very different ways on the site most entity types are also divided into entity subtypes  which are divisions within an entity type to allow for smaller variations in how the entities are used and displayed for example the content item entity type that stores pagelevel content is divided into content type subtypes the content block entity type has block types  but the user entity type for user profile information does not have subtypes what is a field  within entity items the data is stored in individual fields  each of which holds one type of data such as formatted or plain text images or other files or dates fields can be added by an administrator on entity subtypes so that all entity items of a given entity subtype have the same collection of fields available and they can be singlevalued or multiplevalued when you create or edit entity items you are specifying the values for the fields on the entity item what is a reference field  a reference field is a field that stores a relationship between an entity and one or more other entities which may belong to the same or different entity type for example a content reference field on a content type stores a relationship between one content item and one or more other content items what field types are available  the following field types are provided by the core system and core modules many more are provided by contributed modules boolean number provided by the core system stores true false values and numbers comment provided by the core comment module allows users to add comments to an entity date timestamp datetime module stores dates and times date range datetime range module stores time date periods with a start and an end email core system stores email addresses link link module stores urls and link text list options module stores values chosen from predefined lists where the values can be numbers or text see section below for more on list fields reference core system stores entity references see section above telephone telephone module stores telephone numbers text text module stores formatted and unformatted text see section below for more on text fields what settings are available for list field types  list fields associate predefined keys  or value codes with labels that the user sees for example you might define a list field that shows the user the names of several locations while behind the scenes a location code is stored in the database each list field type corresponds to one type of stored key for example a list integer  field stores integers while the list text  field stores text strings once you have chosen the field type the main setting for a list field is the allowed values list which associates the keys with the labels what types of text fields are available  there are several types of text fields with different characteristics text fields can be either plain or formatted  plain text fields do not contain html while formatted fields can contain html and are processed through text filters  these are provided by the core filter module if you have that module enabled see the related topic below on filters for more information text fields can also be regularlength with a limit of 255 characters or long  with a very large character limit and long formatted text fields can include a summary attribute all possible combinations of these characteristics exist as text field types for example  text plain  and text formatted long with summary  are two examples of text field types what is a formatter  a formatter is a way to display a field most field types offer several types of formatters and most formatters have settings that further define how the field is displayed it is also possible to completely hide a field from display and you have the option of showing or hiding the field s label when it is displayed what is a widget  a widget is a way to edit a field some field types such as plain text singleline fields have only one widget available in this case a singleline text input field other field types offer choices for the widget for example singlevalued list fields can use a select or radio button widget for editing many widget types have settings that further define how the field can be edited managing content structure overview besides the field modules listed in the previous section there are additional core modules that you can use to manage your content structure the core node comment content block custom menu links user file image media taxonomy and contact modules all provide content entity types the core field ui module provides a user interface for managing fields and their display on entities the core layout builder module provides a more flexible user interface for configuring the display of entities the core filter responsive image and path modules provide settings and display options for entities and fields depending on the core and contributed modules that you currently have installed on your site the related topics below and other topics listed on the main help page see help will help you with tasks related to content structure additional resources concept types of data drupal user guide  planning your site drupal user guide  concept reference fields drupal user guide  ',0),(17,'en','node_search',' statelevel swimming championship statelevel swimming championship aryan wed 8202025 635 young and professional swimmers from across the state participate to showcase speed endurance and discipline in water sports sat 8232025 1208 sat 9062025 1208 balewadi stadium pune arunima sinha name first middle last email phone number country none afghanistan albania algeria american samoa andorra angola anguilla antarctica antigua barbuda argentina armenia aruba ascension island australia austria azerbaijan bahamas bahrain bangladesh barbados belarus belgium belize benin bermuda bhutan bolivia bosnia herzegovina botswana bouvet island brazil british indian ocean territory british virgin islands brunei bulgaria burkina faso burundi cambodia cameroon canada canary islands cap